// AtIoFile, AtIoJamFile, AtIoFastAlignedJamFile, AtIoFastJamFile — recovered methods. Original address clusters
// 0x00025B80-0x00025BDA and 0x000827E0-0x00082A98, 0x00082DA0-0x00083165. Also OpenFile and CloseFile of the header classes.
// Verification status per function: config/functions.toml, docs/PROGRESS.md (generated by tools/verify.py).
#include "at/AtIoJam.h"
#include "AtIoJamCommon.h"

AtIoFile::AtIoFile() {
    m_position = 0;
    m_unknown94 = 0;
    m_unknown98 = 0;
    m_size = 0;
    m_sizeCopy = 0;
    m_flags = 0;
}

AtIoFile::~AtIoFile() {
}

int AtIoFile::ResetFile() {
    m_position = 0;
    m_unknown94 = 0;
    m_unknown98 = 0;
    m_size = 0;
    m_sizeCopy = 0;
    m_flags = 0;
    return 0;
}

AtIoJamFile::AtIoJamFile() {
    m_owner = 0;
    m_base = 0;
    m_secondSize = 0;
}

int AtIoJamFile::Clear() {
    m_flags = 0;
    for (int i = 0; i < 0x20; i++) {
        ((unsigned int*)m_path)[i] = 0;
    }
    return 0;
}

void AtIoJamFile::Attach(AtIoJamDirectoryHeader* owner) {
    if (m_owner) {
        Close();
    }
    m_owner = owner;
}

int AtIoJamFile::Close() {
    if (m_owner == 0) {
        return 0;
    }
    for (int i = 0; i < 0x20; i++) {
        ((unsigned int*)m_path)[i] = 0;
    }
    m_owner = 0;
    m_base = 0;
    m_secondSize = 0;
    return ResetFile();
}

int AtIoJamFile::Read(void* out, unsigned int size, unsigned int* done, AtIoFileRequest** request) {
    if (done) {
        *done = 0;
    }
    if (m_owner == 0 || !(m_flags & kOpen)) {
        return kNotFound;
    }
    if (size == 0) {
        return kOk;
    }
    if (m_position >= m_size) {
        m_flags |= kReachedEnd;
        return kEndOfFile;
    }
    if (m_position + size >= m_size) {
        m_flags |= kReachedEnd;
        size = m_size - m_position;
    }
    AtIoFile* archive = m_owner->m_fs->File();
    if (archive->Seek(m_base + m_position) != 0) {
        return kIoError;
    }
    unsigned int before = archive->m_position;
    int status = archive->Read(out, size, done, request);
    m_position += archive->m_position - before;
    return status;
}

int AtIoJamFile::Write(const void*, unsigned int, unsigned int* done) {
    *done = 0;
    return kUnsupported;
}

int AtIoJamFile::Flush() {
    return kUnsupported;
}

int AtIoJamFile::Unknown8(void* request) {
    return m_owner->m_fs->File()->Unknown8(request);
}

int AtIoJamFile::Release(AtIoFileRequest* request) {
    return m_owner->m_fs->File()->Release(request);
}

AtIoFastAlignedJamFile::AtIoFastAlignedJamFile() {
}

AtIoFastAlignedJamFile::~AtIoFastAlignedJamFile() {
    if (m_owner) {
        for (int i = 0; i < 0x20; i++) {
            ((unsigned int*)m_path)[i] = 0;
        }
        m_owner = 0;
        m_base = 0;
        m_secondSize = 0;
        ResetFile();
    }
}

int AtIoFastAlignedJamFile::Open(const char* path, const char* displayName, int flags) {
    Clear();
    m_flags = flags;
    if (flags & kFlagsIgnored) {
        m_flags = flags & ~kFlagsIgnored;
    }
    if (m_flags & kFlagsWrite) {
        m_flags = 0;
        return kUnsupported;
    }
    unsigned int size;
    if (!static_cast<AtIoFastAlignedJamHeader*>(m_owner)->FindFileInfo(path, &m_base, &size)) {
        return kNotFound;
    }
    m_size = size;
    m_sizeCopy = size;
    if (m_owner->m_fs->File()->Seek(m_base) != 0) {
        return kIoError;
    }
    m_flags |= kOpen;
    m_position = 0;
    strcpy(m_path, displayName);
    return kOk;
}

// Original behaviour preserved: the current position is added to the target, unlike AtIoFastJamFile::Seek.
int AtIoFastAlignedJamFile::Seek(unsigned int offset) {
    if (offset >= m_size) {
        return kEndOfFile;
    }
    if (m_owner->m_fs->File()->Seek(m_base + offset + m_position) != 0) {
        return kIoError;
    }
    m_position = offset;
    m_flags &= ~kReachedEnd;
    return kOk;
}

AtIoFastJamFile::AtIoFastJamFile() {
}

AtIoFastJamFile::~AtIoFastJamFile() {
    if (m_owner) {
        for (int i = 0; i < 0x20; i++) {
            ((unsigned int*)m_path)[i] = 0;
        }
        m_owner = 0;
        m_base = 0;
        m_secondSize = 0;
        ResetFile();
    }
}

int AtIoFastJamFile::Open(const char* path, const char* displayName, int flags) {
    Clear();
    m_flags = flags;
    if (flags & kFlagsIgnored) {
        m_flags = flags & ~kFlagsIgnored;
    }
    if (m_flags & kFlagsWrite) {
        m_flags = 0;
        return kUnsupported;
    }
    if (!static_cast<AtIoFastJamHeader*>(m_owner)->GetRecordOffset(path, &m_base)) {
        return kNotFound;
    }
    AtIoFile* archive = m_owner->m_fs->File();
    if (archive->Seek(m_base) != 0) {
        return kIoError;
    }
    unsigned char sizes[8];
    unsigned int done;
    AtIoFileRequest* request;
    int status = archive->Read(sizes, 8, &done, &request);
    if (status == kPending) {
        status = request->Wait();
        archive->Release(request);
    }
    if (status != 0) {
        return kIoError;
    }
    m_size = AtReadU32(sizes);
    m_sizeCopy = m_size;
    m_secondSize = AtReadU32(sizes + 4);
    m_flags |= kOpen;
    m_position = 0;
    m_base += 0x20;
    strcpy(m_path, displayName);
    return kOk;
}

int AtIoFastJamFile::Seek(unsigned int offset) {
    if (offset >= m_size) {
        return kEndOfFile;
    }
    if (m_owner->m_fs->File()->Seek(m_base + offset) != 0) {
        return kIoError;
    }
    m_position = offset;
    m_flags &= ~kReachedEnd;
    return kOk;
}

AtIoJamFile* AtIoJamDirectoryHeader::OpenFile() {
    for (unsigned int i = 0; i < m_fs->m_maxOpen; i++) {
        if (m_files[i].m_owner == 0) {
            m_files[i].Attach(this);
            return &m_files[i];
        }
    }
    return 0;
}

int AtIoJamDirectoryHeader::CloseFile(AtIoFile* file) {
    return file->Close();
}

